import{_ as e,c as a,o as n,ah as t,aE as o,aF as s,aG as r,aH as c,aI as g}from"./chunks/framework.CDL6_Pj-.js";const b=JSON.parse('{"title":"Sponsor","description":"","frontmatter":{},"headers":[],"relativePath":"sponsor.md","filePath":"sponsor.md"}'),l={name:"sponsor.md"};function d(p,i,h,m,u,f){return n(),a("div",null,[...i[0]||(i[0]=[t('<h1 id="sponsor" tabindex="-1">Sponsor <a class="header-anchor" href="#sponsor" aria-label="Permalink to “Sponsor”">​</a></h1><h2 id="shanghai-point-imaging-healthcare-co-ltd" tabindex="-1">Shanghai Point Imaging Healthcare Co., Ltd. <a class="header-anchor" href="#shanghai-point-imaging-healthcare-co-ltd" aria-label="Permalink to “Shanghai Point Imaging Healthcare Co., Ltd.”">​</a></h2><p><img src="'+o+'" alt="Point Imaging logo" style="display:block;margin:16px auto 20px auto;max-width:300px;height:auto;"></p><p>Founded on August 20, 2024, <strong>Shanghai Point Imaging Healthcare Co., Ltd.</strong> is headquartered in the <strong>Grand NeoBay</strong> science and innovation hub in Minhang District, Shanghai. The company’s core technology is derived from the commercialization of research achievements from the <strong>National Engineering Research Center for Advanced Magnetic Resonance Diagnosis and Treatment Technology at Shanghai Jiao Tong University</strong>. Powered by cutting-edge innovation and strong academic expertise, Point Imaging is committed to becoming a leading benchmark enterprise in the medical technology industry.</p><p>Point Imaging is dedicated to advancing the accessibility of magnetic resonance technology in primary healthcare and continuously improving the experience of both clinicians and patients, enabling more people to benefit from advanced medical imaging. Its flagship product, a <strong>mobile low-field MRI system</strong>, is designed to bring magnetic resonance imaging beyond conventional fixed facilities into a wider range of clinical settings, including <strong>bedside care, emergency medicine, intensive care, and grassroots healthcare institutions</strong>. With greater flexibility, lower infrastructure dependence, and stronger adaptability to diverse medical scenarios, the system supports the development of more inclusive, efficient, and patient-centered imaging services.</p><p><img src="'+s+'" alt="Point Imaging logo" style="display:block;margin:16px auto 20px auto;max-width:500px;height:auto;"></p><p>The piMR-820H is a highly mobile, patient-friendly, and technologically advanced MRI solution designed to bring precision imaging directly to the point of care. By integrating core distortion-reduction technology with a flexible dual-power system, it empowers clinicians to perform high-quality diagnostics in any setting, driving the future of bedside precision medicine.</p><p><img src="'+r+'" alt="Point Imaging logo" style="display:block;margin:16px auto 20px auto;max-width:500px;height:auto;"></p><p>The piMR-820H provides essential clinical contrasts, including T1-weighted, T2-weighted, and FLAIR imaging. Despite operating at a lower field strength, it delivers diagnostic performance comparable to conventional superconducting MRI systems, enabling accurate clinical diagnose across a wide range of neurological and systemic applications at the point of care.</p><p><img src="'+c+'" alt="Point Imaging logo" style="display:block;margin:16px auto 20px auto;max-width:500px;height:auto;"></p><p>The piMR-820H system delivers clinically relevant brain imaging, demonstrating comparable visualization of meningioma and post-stroke lesions to high-field MRI, facilitating reliable assessment and follow-up care.</p><p><img src="'+g+'" alt="Point Imaging logo" style="display:block;margin:16px auto 20px auto;max-width:500px;height:auto;"></p><p>Mobile MRI with DTI capability enables visualization of brain microstructure, supporting advanced neurological assessment.</p>',13)])])}const _=e(l,[["render",d]]);export{b as __pageData,_ as default};
